{
  "incident_id": "challenge-mixed-evidence",
  "telemetry_version": 1,
  "assessment": "Confirmed active exfiltration from critical host web-01 to c2-01 and confirmed lateral movement attempts from web-01. Workstation-01 activity is verified authorized. Immediate containment of web-01 egress and lateral movement is required to stop data loss and prevent further spread.",
  "evidence_review": [
    {
      "evidence_id": "E1",
      "decision": "contain",
      "reason": "Confirmed active unauthorized data transfer from web-01 to c2-01. Blocking egress to c2-01 from web-01 stops the exfiltration."
    },
    {
      "evidence_id": "E2",
      "decision": "contain",
      "reason": "Confirmed unauthorized lateral access attempt originating on web-01. Restricting lateral traffic from web-01 prevents further lateral movement."
    },
    {
      "evidence_id": "M3",
      "decision": "no_action",
      "reason": "Activity on workstation-01 is an approved scheduled backup matching change records. No malicious activity observed; no action required."
    }
  ],
  "actions": [
    {
      "kind": "block_egress",
      "target_id": "c2-01",
      "scope_host_ids": [
        "web-01"
      ],
      "evidence_ids": [
        "E1"
      ],
      "reason": "Blocks the confirmed active exfiltration path from web-01 to c2-01. This is the minimal control to stop data loss. Management and evidence channels are preserved.",
      "ttl_minutes": 30,
      "preserve_channels": [
        "management",
        "evidence_collector"
      ],
      "rollback": "managed_by_simulator"
    },
    {
      "kind": "restrict_lateral",
      "target_id": "web-01",
      "scope_host_ids": [],
      "evidence_ids": [
        "E2"
      ],
      "reason": "Restricts lateral movement from web-01 to contain the confirmed lateral access attempt. This prevents spread to other assets while preserving management access for forensic collection.",
      "ttl_minutes": 30,
      "preserve_channels": [
        "management",
        "evidence_collector"
      ],
      "rollback": "managed_by_simulator"
    }
  ],
  "uncertainties": [
    "Availability impact of blocking egress and restricting lateral traffic on web-01 is unknown as dependency data is not provided, though management access is preserved."
  ],
  "peer_responses": [],
  "review_after_seconds": 60
}

{
  "incident_id": "challenge-protected-c2",
  "telemetry_version": 1,
  "assessment": "Confirmed active exfiltration from critical host web-01 to protected destination c2-01. Immediate containment of the exfiltration channel is required. Full isolation of the critical host is prohibited by policy; targeted egress blocking is the minimal sufficient control.",
  "evidence_review": [
    {
      "evidence_id": "M1",
      "decision": "contain",
      "reason": "Confirmed unauthorized sensitive-data exfiltration from web-01 to c2-01. Evidence explicitly authorizes block_egress to stop the data loss."
    }
  ],
  "actions": [
    {
      "kind": "block_egress",
      "target_id": "c2-01",
      "scope_host_ids": [
        "web-01"
      ],
      "evidence_ids": [
        "M1"
      ],
      "reason": "Interrupts the confirmed exfiltration channel from the critical host web-01 to the C2 destination c2-01. This targeted restriction preserves the critical host's availability and management access while stopping data loss, adhering to the policy prohibition on full isolation of critical assets.",
      "ttl_minutes": 30,
      "preserve_channels": [
        "management",
        "evidence_collector"
      ],
      "rollback": "managed_by_simulator"
    }
  ],
  "uncertainties": [
    "Availability impact on web-01 services dependent on c2-01 is unknown as dependency metadata is not provided, though the host is not isolated."
  ],
  "peer_responses": [],
  "review_after_seconds": 60
}

{
  "incident_id": "challenge-protected-c2",
  "telemetry_version": 1,
  "assessment": "Confirmed active exfiltration from critical host web-01 to protected destination c2-01. Direct blocking of egress to the protected destination c2-01 is prohibited by policy. Containment must focus on the source host to stop the exfiltration while preserving the protected destination.",
  "evidence_review": [
    {
      "evidence_id": "M1",
      "decision": "contain",
      "reason": "Evidence M1 confirms active unauthorized data exfiltration from web-01 to c2-01. This is a confirmed threat requiring immediate containment of the source."
    }
  ],
  "actions": [
    {
      "kind": "block_egress",
      "target_id": "web-01",
      "scope_host_ids": [
        "web-01"
      ],
      "evidence_ids": [
        "M1"
      ],
      "reason": "Evidence M1 confirms web-01 is exfiltrating data. Blocking egress from web-01 stops the exfiltration. Since the destination c2-01 is protected and cannot be blocked directly, the source must be restricted. This action preserves the protected destination c2-01 while containing the threat.",
      "ttl_minutes": 30,
      "preserve_channels": [
        "management",
        "evidence_collector"
      ],
      "rollback": "managed_by_simulator"
    }
  ],
  "uncertainties": [
    "Impact on web-01 availability is unknown as dependency details are not provided, but blocking egress may disrupt legitimate outbound traffic."
  ],
  "peer_responses": [],
  "review_after_seconds": 60
}

